(() => {
'use strict';
const {modules,lessons}=window.ATLAS;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const known=new Set(lessons.map(l=>l.id));
let saved={done:[],bookmarks:[],last:null,theme:'light'};
try{const x=JSON.parse(localStorage.getItem('backend-atlas-v1'));if(x&&typeof x==='object'){saved.done=Array.isArray(x.done)?[...new Set(x.done.filter(id=>known.has(id)))]:[];saved.bookmarks=Array.isArray(x.bookmarks)?[...new Set(x.bookmarks.filter(id=>known.has(id)))]:[];saved.last=known.has(x.last)?x.last:null;saved.theme=x.theme==='dark'?'dark':'light';}}catch{}
let filter='All',timer=null,labCleanup=null,toastTimer=null,searchTimer=null;
const main=$('#main');
const moduleOf=id=>modules.find(m=>m.id===id);
const inModule=id=>lessons.filter(l=>l.module===id);
const badge=l=>`<span class="badge ${l.level==='Intermediate'?'intermediate':l.level==='Advanced'?'advanced':''}">${l.level==='Foundation'?'● ':l.level==='Intermediate'?'◐ ':l.level==='Advanced'?'◆ ':''}${esc(l.level)}</span>`;
function persist(){try{localStorage.setItem('backend-atlas-v1',JSON.stringify(saved));}catch{toast('Browser storage is unavailable. Progress will last for this visit.');}updateProgress();}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function updateProgress(){const n=saved.done.length,p=Math.round(100*n/lessons.length);$('#side-percent').textContent=p+'%';$('#side-fill').style.width=p+'%';$('#side-progress').textContent=`${n} of ${lessons.length} lessons complete`;$('#saved-count').textContent=saved.bookmarks.length;}
function menuAccessibility(){$('#sidebar').inert=matchMedia('(max-width:760px)').matches&&!$('#sidebar').classList.contains('open');}function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').classList.remove('visible');$('#menu-toggle').setAttribute('aria-expanded','false');menuAccessibility();}
function stopActive(){clearInterval(timer);timer=null;if(labCleanup){labCleanup();labCleanup=null;}}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
$('#chapter-nav').innerHTML=modules.map((m,i)=>`<a href="#module/${m.id}" data-module="${m.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><span>${esc(m.title)}</span><span class="count">${inModule(m.id).length}</span></a>`).join('');
$('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#scrim').classList.toggle('visible',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));menuAccessibility();};$('#scrim').onclick=closeMenu;
$('#theme-toggle').onclick=()=>{saved.theme=saved.theme==='dark'?'light':'dark';document.body.classList.toggle('dark',saved.theme==='dark');persist();};document.body.classList.toggle('dark',saved.theme==='dark');
$('#export-progress').onclick=()=>{const payload={course:'Backend Atlas',exportedAt:new Date().toISOString(),completed:saved.done.map(id=>lessons.find(l=>l.id===id).title),saved:saved.bookmarks.map(id=>lessons.find(l=>l.id===id).title)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='backend-atlas-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress exported to your downloads.');};
$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if($('#search').value.trim())showSearch($('#search').value.trim());else render(false);},140);});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}if(e.key==='Escape'){closeMenu();if(document.activeElement===$('#search')){$('#search').value='';$('#search').blur();render();}}});
function activeNav(route,mod){$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));$$('[data-module]').forEach(a=>a.classList.toggle('active',a.dataset.module===mod));}
function heroArt(){return `<div class="hero-art" aria-label="A browser sends requests to an API connected to a database and cache"><div class="hero-diagram"><svg viewBox="0 0 360 280" aria-hidden="true" preserveAspectRatio="none"><path d="M45 150 H195 M225 130 V65 H330 M225 155 V230 H330" fill="none" stroke="#a9b59b" stroke-width="1.3" class="flow-dash"/><path d="M200 170 V205 H85 V180" fill="none" stroke="#c89474" stroke-width="1.1" class="flow-dash"/></svg><div class="hero-node client"><span>▣</span>client<small>the curious browser</small></div><div class="hero-node api"><span>⇄</span>api server<small>making things happen</small></div><div class="hero-node db"><span>▤</span>database<small>the source of truth</small></div><div class="hero-node cache"><span>ϟ</span>cache<small>the fast lane</small></div><span class="hero-label req">01 → request</span><span class="hero-label res">← 04 response</span><span class="hero-stamp">A LITTLE LESS ABSTRACT.</span></div></div>`;}
function chapterCard(m,i){const ls=inModule(m.id),done=ls.filter(l=>saved.done.includes(l.id)).length;return `<a class="chapter-card" href="#module/${m.id}"><div class="card-top"><span class="card-icon">${m.icon}</span><span class="chapter-number">CHAPTER ${String(i+1).padStart(2,'0')}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="card-bottom"><span>${ls.length} lessons <span aria-hidden="true">·</span> ${done?`${done} complete`:'Explore chapter'}</span><span class="arrow">↗</span></div></a>`;}
function row(l,i){const m=moduleOf(l.module);return `<a class="lesson-row" href="#lesson/${l.id}"><span class="row-num">${String(i+1).padStart(2,'0')}</span><div class="row-copy"><h3>${esc(l.title)}</h3><p>${esc(m.title)} <span aria-hidden="true">·</span> ${badge(l)}</p></div>${saved.done.includes(l.id)?'<span class="done" aria-label="Completed">✓</span>':''}<span class="row-time">${l.minutes} min</span><span aria-hidden="true">↗</span></a>`;}
function showHome(){const resume=lessons.find(l=>l.id===saved.last)||lessons.find(l=>l.id==='http-the-request-response-journey');main.innerHTML=`<div class="page-intro"><div class="eyebrow"><span class="dot"></span> A little curiosity. A lot of possibility.</div><span>Your next breakthrough starts here ↙</span></div><section class="hero"><div class="hero-copy"><span class="tag">THE INTERACTIVE BACKEND FIELD GUIDE</span><h1>Understand the backend.<br><em>One moving part<br>at a time.</em></h1><p>Go beyond definitions. Explore the concepts, watch them work, and build the intuition to design better systems.</p><a class="button orange" href="#lesson/${resume.id}">${saved.last?'Continue learning':'Start exploring'} <span>→</span></a><a class="button ghost" href="#path">View the roadmap ↗</a></div>${heroArt()}</section><div class="stats"><div class="stat"><span class="stat-symbol">▤</span><div><strong>120</strong><small>Deep-dive lessons</small></div></div><div class="stat"><span class="stat-symbol">⌘</span><div><strong>17</strong><small>Connected chapters</small></div></div><div class="stat"><span class="stat-symbol">⇄</span><div><strong>240</strong><small>Real-world examples</small></div></div><div class="stat"><span class="stat-symbol">▷</span><div><strong>120</strong><small>Visual walkthroughs</small></div></div></div><div class="section-heading"><div><h2>${saved.last?'Pick up where you left off':'A good place to begin'}</h2><p>Less memorizing. More “oh, that makes sense.”</p></div><a href="#playground">Explore the playground ↗</a></div><section class="featured"><div class="feature-copy"><div class="eyebrow">${saved.last?'YOUR LAST LESSON':'SPOTLIGHT LESSON'} <span style="color:var(--orange)">✦</span></div><h3>${esc(resume.title)}</h3><p>${saved.last?'Keep building your understanding with two practical examples and a step-by-step visual model.':'What really happens between clicking a button and getting a response? Follow every step of the journey.'}</p><div class="feature-meta">${badge(resume)}<span>${resume.minutes} min read</span><span>Interactive</span></div><a class="button secondary small" href="#lesson/${resume.id}">Open lesson <span>→</span></a></div><div class="feature-art"><div class="mini-chain"><div class="mini-box"><b>▣</b>client</div><div class="mini-edge"></div><div class="mini-box"><b>⇄</b>server</div><div class="mini-edge"></div><div class="mini-box"><b>▤</b>database</div></div><span class="floating-caption"><i></i> PRESS PLAY. FOLLOW THE REQUEST.</span></div></section><div class="section-heading"><div><h2>Your backend, from the ground up</h2><p>A connected curriculum. Follow the path or follow your curiosity.</p></div><div class="curriculum-tools" role="group" aria-label="Filter chapters">${['All','Foundations','Backend','Architecture'].map(x=>`<button class="filter-button ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div></div><div class="cards" id="home-cards">${filteredCards()}</div><div class="note-card"><div><h3>Ideas make more sense when you can play with them.</h3><p>Experiment with HTTP, caching, queues, rate limits, and more in a safe little sandbox.</p></div><a class="button secondary small" href="#playground">Open playground ↗</a></div>`;$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));$('#home-cards').innerHTML=filteredCards();});}
function filteredCards(){const groups={Foundations:['foundations','networking','runtimes'],Backend:['apis','databases','caching','security','messaging','resilience','performance','testing'],Architecture:['architecture','systems','designs','lld','devops','projects']};return modules.map((m,i)=>({m,i})).filter(({m})=>filter==='All'||groups[filter].includes(m.id)).map(({m,i})=>chapterCard(m,i)).join('');}
function showModule(m){const ls=inModule(m.id),n=modules.indexOf(m)+1;main.innerHTML=`<div class="view-title"><div class="eyebrow">CHAPTER ${String(n).padStart(2,'0')} / 17</div><h1>${esc(m.title)}</h1><p>${esc(m.description)} Every lesson pairs the mental model with two concrete examples and a labeled visual walkthrough.</p></div><div class="chapter-progress">${ls.length} lessons <span aria-hidden="true">·</span> ${ls.filter(l=>saved.done.includes(l.id)).length} completed</div><div class="list">${ls.map(row).join('')}</div><div class="note-card"><div><h3>Learn at your own pace.</h3><p>Mark a lesson complete when you can explain its trade-offs in your own words.</p></div><a class="button secondary small" href="#lesson/${ls.find(l=>!saved.done.includes(l.id))?.id||ls[0].id}">Start this chapter →</a></div>`;}
function showPath(){main.innerHTML=`<div class="view-title"><div class="eyebrow">THE BIG PICTURE</div><h1>A path from fundamentals to systems.</h1><p>Start with the foundations, connect the pieces, then put them to work. Open a chapter to see its lessons. Your progress stays in this browser.</p></div>${modules.map((m,i)=>{const ls=inModule(m.id);return `<details class="path-module" ${i===0?'open':''}><summary><span class="path-num">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(m.title)}</h2><p>${ls.length} lessons · ${ls.filter(l=>saved.done.includes(l.id)).length} completed</p></div></summary><div class="list">${ls.map(row).join('')}</div></details>`;}).join('')}<p class="utility-note">Green: foundation · Amber: intermediate · Red: advanced. Design exercises and projects apply several levels together.</p>`;}
function showSaved(){const ls=lessons.filter(l=>saved.bookmarks.includes(l.id));main.innerHTML=`<div class="view-title"><div class="eyebrow">YOUR REFERENCE SHELF</div><h1>Keep the useful bits close.</h1><p>Save a lesson with the bookmark button when you want to revisit it. These bookmarks and completion marks are stored on this device.</p></div>${ls.length?`<div class="list">${ls.map(row).join('')}</div>`:`<div class="empty"><h2>Your shelf is ready.</h2><p>Open a lesson and choose “Save lesson” to add your first bookmark.</p><a class="button orange" href="#path">Explore the learning path →</a></div>`}`;}
function showSearch(q){stopActive();closeMenu();activeNav('',null);$('#crumb').textContent='Search';document.title='Search — Backend Atlas';const terms=q.toLowerCase().split(/\s+/),results=lessons.filter(l=>{const hay=[l.title,l.concept,l.deep,l.pitfall,...l.examples,moduleOf(l.module).title].join(' ').toLowerCase();return terms.every(t=>hay.includes(t));});main.innerHTML=`<div class="view-title"><div class="eyebrow">SEARCH THE FIELD GUIDE</div><h1>Follow your curiosity.</h1></div><div class="search-heading"><h2>Results for “${esc(q)}”</h2><span>${results.length} lesson${results.length===1?'':'s'}</span></div>${results.length?`<div class="list">${results.map(row).join('')}</div>`:`<div class="empty"><h2>No lessons found.</h2><p>Try a shorter phrase like “Kafka”, “async”, “index” or “saga”.</p><button class="button secondary" id="clear-search">Clear search</button></div>`}`;if($('#clear-search'))$('#clear-search').onclick=()=>{$('#search').value='';render();};}
const labs=[['http','HTTP request lab','Send a request. Inspect the response.','⇄'],['cache','LRU cache lab','Fill a tiny cache and cause an eviction.','ϟ'],['rate','Token bucket','Spend tokens. Advance time. Try a burst.','◷'],['balance','Load balancer','Route traffic and take a server offline.','▦'],['queue','Queue & worker lab','Add jobs, change workers, step time.','≋'],['binary','Binary search','Watch the search space shrink.','⌕'],['isolation','Transaction isolation','Interleave reads and a committed write.','▤'],['circuit','Circuit breaker','Fail a dependency. Probe its recovery.','↻'],['shard','Hash sharding','Compare modulo routing as nodes change.','⬡']];
function labFor(l){if(l.id.startsWith('http-the-'))return'http';if(l.id.startsWith('lru-lfu-'))return'cache';if(l.id.startsWith('rate-limiting-'))return'rate';if(l.id==='scaling-load-balancing-proxies')return'balance';if(l.id.startsWith('celery-'))return'queue';if(l.id==='sorting-binary-search')return'binary';if(l.id.startsWith('isolation-levels-'))return'isolation';if(l.id.startsWith('circuit-breakers-'))return'circuit';if(l.id==='sharding-routing-rebalancing')return'shard';return null;}
function showLesson(l){const m=moduleOf(l.module),index=lessons.indexOf(l),done=saved.done.includes(l.id),book=saved.bookmarks.includes(l.id),next=lessons[index+1],special=labFor(l);saved.last=l.id;persist();main.innerHTML=`<div class="lesson-header"><a class="eyebrow" href="#module/${m.id}">← ${esc(m.title)}</a><h1>${esc(l.title)}</h1><div class="lesson-top-meta">${badge(l)}<span>${l.minutes} min + exploration</span><span>2 examples</span><span>Interactive walkthrough</span></div><div class="lesson-toolbar"><button id="mark-done" class="button ${done?'secondary':'orange'}">${done?'✓ Completed':'Mark complete'}</button><button id="bookmark" class="button secondary">${book?'◆ Saved':'♧ Save lesson'}</button><button id="print-lesson" class="button secondary" aria-label="Print this lesson">↗ Print</button></div></div><div class="lesson-body"><article class="reading"><section class="lesson-section" id="understand"><h2><span class="section-index">01</span> The mental model</h2><div class="prose"><p>${esc(l.concept)}</p><p>${esc(l.deep)}</p></div></section><section class="lesson-section" id="examples"><h2><span class="section-index">02</span> Two simple examples</h2><div class="examples">${l.examples.map((e,i)=>`<div class="example"><span class="example-number">0${i+1}</span><div><h3>${i===0?'Make it concrete':'See another angle'}</h3><p>${esc(e)}</p></div></div>`).join('')}</div></section><section class="lesson-section" id="simulate"><h2><span class="section-index">03</span> See the moving parts</h2><p class="lab-caption">Play the walkthrough or move one step at a time. Each numbered stage highlights the component handling the work.</p><div id="trace-host"></div>${special?`<div style="height:22px"></div><div id="lesson-lab"></div>`:''}</section><section class="lesson-section" id="tradeoffs"><h2><span class="section-index">04</span> The detail to remember</h2><div class="watchout"><strong>KEEP THIS IN MIND</strong>${esc(l.pitfall)}</div></section><section class="lesson-section" id="resources"><h2><span class="section-index">05</span> Another way to learn it</h2>${videoHTML(l)}<div class="references">${l.references.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`).join('')}</div><p class="all-saved-note">Videos and reference documentation open online. The lessons and simulations run entirely in your browser.</p></section><div class="lesson-next"><button class="button ${done?'secondary':'orange'}" id="bottom-done">${done?'✓ Completed':'I understand this · Mark complete'}</button>${next?`<a class="next-link" href="#lesson/${next.id}">UP NEXT →<b>${esc(next.title)}</b></a>`:`<a class="next-link" href="#path">BACK TO YOUR LEARNING PATH →</a>`}</div></article><aside class="lesson-outline"><small>IN THIS LESSON</small><a href="#understand" data-anchor="understand">01 &nbsp; The mental model</a><a href="#examples" data-anchor="examples">02 &nbsp; Two simple examples</a><a href="#simulate" data-anchor="simulate">03 &nbsp; Interactive model</a><a href="#tradeoffs" data-anchor="tradeoffs">04 &nbsp; Trade-offs</a><a href="#resources" data-anchor="resources">05 &nbsp; Videos & resources</a><div class="outline-note">Try explaining this concept to a friend. If you can describe when to use it and when it fails, you’re building real intuition.</div></aside></div>`;
function toggleDone(){const had=saved.done.includes(l.id);saved.done=had?saved.done.filter(x=>x!==l.id):[...saved.done,l.id];persist();const now=!had;['#mark-done','#bottom-done'].forEach(id=>{const b=$(id);b.textContent=now?'✓ Completed':id==='#mark-done'?'Mark complete':'I understand this · Mark complete';b.className='button '+(now?'secondary':'orange');});toast(now?'Lesson complete. One more piece connected.':'Lesson marked incomplete.');}
$('#mark-done').onclick=toggleDone;$('#bottom-done').onclick=toggleDone;$('#bookmark').onclick=()=>{const had=saved.bookmarks.includes(l.id);saved.bookmarks=had?saved.bookmarks.filter(x=>x!==l.id):[...saved.bookmarks,l.id];persist();$('#bookmark').textContent=had?'♧ Save lesson':'◆ Saved';toast(had?'Removed from saved lessons.':'Added to your reference shelf.');};$('#print-lesson').onclick=()=>window.print();$$('[data-anchor]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.anchor).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
mountTrace($('#trace-host'),l);if(special)mountLab($('#lesson-lab'),special);if(l.video)$('#load-video').onclick=()=>{const frame=document.createElement('iframe');frame.className='video-frame';frame.title=l.video[1];frame.src='https://www.youtube-nocookie.com/embed/'+l.video[0];frame.loading='lazy';frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';frame.allowFullscreen=true;$('#video-embed').replaceChildren(frame);$('#load-video').hidden=true;};}
function videoHTML(l){if(l.video){const [id,title,creator]=l.video;return `<div class="video-card"><span class="video-icon">▷</span><div class="video-copy"><h3>${esc(title)}</h3><p>${esc(creator)} · Topic explainer on YouTube</p></div><button class="button secondary small" id="load-video">Load video ▷</button></div><div id="video-embed"></div><p class="utility-note"><a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Open directly on YouTube ↗</a></p>`;}return `<div class="video-card"><span class="video-icon">▷</span><div class="video-copy"><h3>Find an explanation that clicks.</h3><p>Search YouTube for this specific topic. Results are external and not individually curated.</p></div><a class="button secondary small" href="${esc(l.searchVideo)}" target="_blank" rel="noopener noreferrer">Find a video ↗</a></div>`;}
function mountTrace(host,l){let step=-1,playing=false;host.innerHTML=`<div class="simulation"><div class="sim-top"><span class="sim-title"><span class="live-dot"></span> INTERACTIVE WALKTHROUGH</span><small>Guided model · ${l.steps.length} stages</small></div><div class="sim-scene"><div class="trace-nodes">${l.nodes.map((n,i)=>`<div class="trace-node" data-node="${i}" data-order="${i+1}"><span class="node-no">0${i+1}</span><span>${esc(n)}</span><span class="node-state">waiting</span></div>`).join('')}</div><div class="sim-step-text" aria-live="polite"><b data-stage>READY WHEN YOU ARE</b><p data-step>Press play to follow the sequence, or use “Next step” to explore at your own pace.</p></div></div><div class="trace-progress">${l.steps.map(()=>'<i></i>').join('')}</div><div class="sim-controls"><button class="button orange small" data-play>▷ Play</button><button class="button secondary small" data-next>Next step →</button><button class="button secondary small" data-reset>↻ Reset</button><span class="sim-position" data-position>00 / 0${l.steps.length}</span></div><p class="sim-note">A simplified teaching model of ${esc(l.title.toLowerCase())}. Timing is illustrative, not a real benchmark.</p></div>`;
const play=$('[data-play]',host),next=$('[data-next]',host);function pause(){clearInterval(timer);timer=null;playing=false;play.textContent=step===l.steps.length-1?'↻ Replay':'▷ Play';}function update(){const active=step<0?-1:Math.min(step,l.nodes.length-1);$$('[data-node]',host).forEach((n,i)=>{n.classList.toggle('active',i===active);n.classList.toggle('passed',i<active);$('.node-state',n).textContent=i===active?(step===l.steps.length-1?'complete':'active'):i<active?'processed':'waiting';});$('[data-stage]',host).textContent=step<0?'READY WHEN YOU ARE':`STAGE ${String(step+1).padStart(2,'0')} · ${l.nodes[active]}`;$('[data-step]',host).textContent=step<0?'Press play to follow the sequence, or use “Next step” to explore at your own pace.':l.steps[step];$('[data-position]',host).textContent=`${String(step+1).padStart(2,'0')} / ${String(l.steps.length).padStart(2,'0')}`;$$('.trace-progress i',host).forEach((n,i)=>n.classList.toggle('filled',i<=step));next.disabled=step===l.steps.length-1;}
function advance(){if(step<l.steps.length-1){step++;update();}if(step===l.steps.length-1)pause();}play.onclick=()=>{if(playing){pause();return;}if(step===l.steps.length-1)step=-1;playing=true;play.textContent='Ⅱ Pause';advance();if(playing)timer=setInterval(advance,2300);};next.onclick=()=>{pause();advance();};$('[data-reset]',host).onclick=()=>{pause();step=-1;update();};}
function showPlayground(id='http'){if(!labs.some(l=>l[0]===id))id='http';main.innerHTML=`<div class="view-title"><div class="eyebrow">THE PLAYGROUND</div><h1>Turn “what if” into “now I get it.”</h1><p>Change an input. Follow the state. Break something safely. These nine browser-only experiments make the mechanics tangible.</p></div><div class="play-grid">${labs.map(([key,title,sub,icon])=>`<a class="play-card ${id===key?'active':''}" href="#playground/${key}"><span class="play-icon">${icon}</span><h3>${title}</h3><p>${sub}</p></a>`).join('')}</div><div id="playground-host"></div><p class="utility-note">All values here are teaching models. No real HTTP requests, broker tasks, payments, or database writes are performed.</p>`;mountLab($('#playground-host'),id);}
function mountLab(host,type){const info=labs.find(x=>x[0]===type);host.innerHTML=`<div class="lab-panel"><div class="lab-heading"><div><h3>${info[1]}</h3><p>${info[2]}</p></div><span class="badge">LIVE MODEL</span></div><div class="lab-inner" data-lab-body></div></div>`;const root=$('[data-lab-body]',host);const log=(el,t)=>{el.textContent=t+'\n'+el.textContent;const lines=el.textContent.split('\n');if(lines.length>18)el.textContent=lines.slice(0,18).join('\n');};
if(type==='http'){
let tick=null,phase=-1,seq=0,busy=false;root.innerHTML=`<p class="lab-caption">Choose a method and server outcome. Send one request, then follow labeled request and response stages. The connection is assumed established.</p><div class="control-row"><label>HTTP method<select data-method><option>GET</option><option>POST</option><option>DELETE</option></select></label><label>Server outcome<select data-outcome><option value="success">Success</option><option value="404">Not found (404)</option><option value="500">Server error (500)</option></select></label><button class="button orange" data-send>Send request →</button><button class="button secondary" data-http-step>Next stage</button><button class="button secondary" data-http-reset>↻ Reset</button></div><div class="trace-nodes">${['Browser client','Request in transit','API + storage','Response → client'].map((n,i)=>`<div class="trace-node" data-http-node="${i}" data-order="${i+1}"><span class="node-no">0${i+1}</span>${n}<span class="node-state">waiting</span></div>`).join('')}</div><div class="http-packet-track"><span class="packet-end">CLIENT</span><span class="http-packet" data-packet>request →</span><span class="packet-end">SERVER</span></div><div class="http-wire"><div class="wire-box"><small>REQUEST</small><pre data-request>Choose a method and send a request.</pre></div><div class="wire-box"><small>RESPONSE</small><pre data-response>Waiting for the server…</pre></div></div><div class="console" data-http-log aria-live="polite">Ready. No real network call will be made.</div>`;
const send=$('[data-send]',root),stepB=$('[data-http-step]',root),ml=$('[data-method]',root),out=$('[data-outcome]',root);let method,outcome,status,body,path;stepB.disabled=true;
function update(){ const packet=$('[data-packet]',root);packet.style.left=['0%','43%','calc(100% - 95px)','0%'][phase];packet.textContent=phase===3?'← response':method+' request →';packet.classList.toggle('returning',phase===3); $$('[data-http-node]',root).forEach((n,i)=>{n.classList.toggle('active',i===phase);n.classList.toggle('passed',i<phase);$('.node-state',n).textContent=i===phase?'active':i<phase?'processed':'waiting';});const msgs=[`${seq}. CLIENT → builds ${method} ${path}`,`${seq}. NETWORK → request bytes travel to the server`,`${seq}. SERVER → routes, validates, and ${outcome==='success'?'performs the storage operation':'produces the selected error'}`,`${seq}. SERVER → CLIENT: ${status}. Browser receives the response.`];log($('[data-http-log]',root),msgs[phase]);if(phase===3){$('[data-response]',root).textContent=`HTTP/1.1 ${status}\n${body?'Content-Type: application/json\n':''}${method==='POST'&&outcome==='success'?'Location: /products/43\n':''}\n${body}`;clearInterval(tick);busy=false;send.disabled=false;stepB.disabled=true;ml.disabled=false;out.disabled=false;}}
function advance(){if(phase<3){phase++;update();}}
function start(){if(busy)return;seq++;phase=-1;busy=true;method=ml.value;outcome=out.value;path=method==='POST'?'/products':'/products/42';status=outcome!=='success'?(outcome==='404'?'404 Not Found':'500 Internal Server Error'):method==='POST'?'201 Created':method==='DELETE'?'204 No Content':'200 OK';body=outcome!=='success'?JSON.stringify({error:outcome==='404'?'Product not found':'Unexpected server failure'}):method==='DELETE'?'':JSON.stringify({id:method==='POST'?43:42,name:'Notebook',price:120});$('[data-request]',root).textContent=`${method} ${path} HTTP/1.1\nHost: api.atlas.local\nAccept: application/json\n${method==='POST'?'Content-Type: application/json\n\n{"name":"Notebook","price":120}':''}`;$('[data-response]',root).textContent='Waiting for the server…';send.disabled=true;stepB.disabled=false;ml.disabled=true;out.disabled=true;advance();tick=setInterval(advance,1300);}
send.onclick=start;stepB.onclick=()=>{clearInterval(tick);advance();};$('[data-http-reset]',root).onclick=()=>{clearInterval(tick);phase=-1;busy=false;send.disabled=false;stepB.disabled=true;ml.disabled=false;out.disabled=false;$$('[data-http-node]',root).forEach(n=>{n.classList.remove('active','passed');$('.node-state',n).textContent='waiting';});$('[data-request]',root).textContent='Choose a method and send a request.';$('[data-response]',root).textContent='Waiting for the server…';const packet=$('[data-packet]',root);packet.style.left='0%';packet.textContent='request →';packet.classList.remove('returning');$('[data-http-log]',root).textContent='Reset. Ready for a new request.';};labCleanup=()=>clearInterval(tick);
}
if(type==='cache'){
let keys=[],hits=0,misses=0;root.innerHTML=`<p class="lab-caption">This cache holds three products. Read a key to load it or refresh its recency. The leftmost entry is least recently used.</p><div class="control-row"><label>Product key<select data-key>${['A','B','C','D','E'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="button orange" data-read>Read key →</button><button class="button secondary" data-flush>Flush cache</button></div><div class="kv-row" data-keys></div><div class="live-metrics"><div><strong data-hits>0</strong><small>Cache hits</small></div><div><strong data-misses>0</strong><small>Database reads</small></div><div><strong data-ratio>0%</strong><small>Hit ratio</small></div></div><div class="console" data-cache-log aria-live="polite">Empty cache. Try A → B → C → A → D.</div>`;function draw(){$('[data-keys]',root).innerHTML=keys.length?keys.map((x,i)=>`<div class="kv-item ${i===keys.length-1?'hot':''}">${x}<small style="display:block;font:8px sans-serif;margin-top:5px">${i===0?'LRU':i===keys.length-1?'MRU':'cached'}</small></div>`).join(''):'<span class="lab-caption">[ empty · capacity 3 ]</span>';$('[data-hits]',root).textContent=hits;$('[data-misses]',root).textContent=misses;$('[data-ratio]',root).textContent=(hits+misses?Math.round(hits*100/(hits+misses)):0)+'%';}draw();$('[data-read]',root).onclick=()=>{const key=$('[data-key]',root).value;if(keys.includes(key)){hits++;keys=keys.filter(x=>x!==key);log($('[data-cache-log]',root),`HIT ${key}: no database read. Move to most recently used.`);}else{misses++;let evicted='';if(keys.length===3)evicted=keys.shift();log($('[data-cache-log]',root),`MISS ${key}: read database.${evicted?' Evict LRU '+evicted+'.':''} Cache ${key}.`);}keys.push(key);draw();};$('[data-flush]',root).onclick=()=>{keys=[];hits=0;misses=0;draw();$('[data-cache-log]',root).textContent='Cache and counters reset.';};
}
if(type==='rate'){
let tokens=5,t=0,accepted=0,rejected=0;root.innerHTML=`<p class="lab-caption">Capacity: 5 tokens. Refill: 1 token/second. Each request costs 1. Time advances only when you choose “+1 second”.</p><div class="control-row"><button class="button orange" data-one>Send request</button><button class="button secondary" data-burst>Send burst of 6</button><button class="button secondary" data-time>+1 second</button><button class="button secondary" data-rate-reset>↻ Reset</button></div><div class="tokens" data-tokens></div><div class="live-metrics"><div><strong data-clock>0s</strong><small>Model time</small></div><div><strong data-accepted>0</strong><small>Accepted</small></div><div><strong data-rejected>0</strong><small>429 rejected</small></div></div><div class="console" data-rate-log aria-live="polite">Ready. Five requests can arrive immediately.</div>`;function draw(){$('[data-tokens]',root).innerHTML=Array.from({length:5},(_,i)=>`<span class="token ${i<tokens?'filled':''}">${i<tokens?'●':'○'}</span>`).join('');$('[data-clock]',root).textContent=t+'s';$('[data-accepted]',root).textContent=accepted;$('[data-rejected]',root).textContent=rejected;}function req(){if(tokens>0){tokens--;accepted++;log($('[data-rate-log]',root),`t=${t}s · ALLOW: consume 1, ${tokens} left.`);}else{rejected++;log($('[data-rate-log]',root),`t=${t}s · 429: no token. Retry after 1 model second.`);}draw();}draw();$('[data-one]',root).onclick=req;$('[data-burst]',root).onclick=()=>{for(let i=0;i<6;i++)req();};$('[data-time]',root).onclick=()=>{t++;tokens=Math.min(5,tokens+1);log($('[data-rate-log]',root),`t=${t}s · refill 1, capped at 5. Available: ${tokens}.`);draw();};$('[data-rate-reset]',root).onclick=()=>{tokens=5;t=0;accepted=0;rejected=0;draw();$('[data-rate-log]',root).textContent='Reset: five tokens available.';};
}
if(type==='balance'){
let counts=[0,0,0],online=[true,true,true],next=0,last=-1;root.innerHTML=`<p class="lab-caption">Round robin sends each new request to the next healthy backend. Toggle a server to see routing skip it. Counts represent assigned requests, not active connections.</p><div class="control-row"><button class="button orange" data-route>Route one request →</button><button class="button secondary" data-route-many>Route 10</button><button class="button secondary" data-lb-reset>↻ Reset</button></div><div class="server-row" data-servers></div><div class="console" data-lb-log aria-live="polite">A, B, and C are online.</div>`;function draw(){$('[data-servers]',root).innerHTML=counts.map((x,i)=>`<div class="server ${last===i?'selected':''}"><small>SERVER ${'ABC'[i]}</small><b>${x}</b><small>assigned requests</small><button class="button secondary small" style="display:block;margin:10px auto 0" data-toggle-server="${i}">${online[i]?'● Online':'○ Offline'}</button></div>`).join('');$$('[data-toggle-server]',root).forEach(b=>b.onclick=()=>{const i=+b.dataset.toggleServer;online[i]=!online[i];log($('[data-lb-log]',root),`Server ${'ABC'[i]} is now ${online[i]?'online':'offline'}.`);draw();});}function route(){if(!online.some(Boolean)){log($('[data-lb-log]',root),'503 Service Unavailable: no healthy backends.');return;}let i=next;while(!online[i])i=(i+1)%3;counts[i]++;next=(i+1)%3;last=i;log($('[data-lb-log]',root),`Request routed to ${'ABC'[i]}. Next search begins at ${'ABC'[next]}.`);draw();}draw();$('[data-route]',root).onclick=route;$('[data-route-many]',root).onclick=()=>{for(let i=0;i<10;i++)route();};$('[data-lb-reset]',root).onclick=()=>{counts=[0,0,0];online=[true,true,true];next=0;last=-1;draw();$('[data-lb-log]',root).textContent='All backends reset and online.';};
}
if(type==='queue'){
let pending=[],running=[],completed=0,t=0,id=0;root.innerHTML=`<p class="lab-caption">Each job takes 3 model seconds. A worker runs one job at a time. Queue capacity is 8 waiting jobs. Workers are assigned at the next time step.</p><div class="control-row"><label>Worker count<select data-workers><option>1</option><option selected>2</option><option>3</option><option>4</option></select></label><button class="button orange" data-enqueue>+ Add job</button><button class="button secondary" data-enqueue-many>+ Add 5 jobs</button><button class="button secondary" data-tick>+1 second</button><button class="button secondary" data-q-reset>↻ Reset</button></div><div data-queue-state></div><div class="live-metrics"><div><strong data-q-time>0s</strong><small>Model time</small></div><div><strong data-q-wait>0</strong><small>Waiting</small></div><div><strong data-q-done>0</strong><small>Completed</small></div></div><div class="console" data-q-log aria-live="polite">Ready. Add jobs, then advance time.</div>`;function draw(){$('[data-queue-state]',root).innerHTML=`<p class="lab-caption">WAITING · FIFO</p><div class="kv-row">${pending.length?pending.map(j=>`<span class="kv-item">job ${j}</span>`).join(''):'<span class="lab-caption">Queue empty</span>'}</div><p class="lab-caption" style="margin-top:18px">RUNNING</p><div class="kv-row">${running.length?running.map(j=>`<span class="kv-item hot">job ${j.id} · ${j.remaining}s left</span>`).join(''):'<span class="lab-caption">No jobs running</span>'}</div>`;$('[data-q-time]',root).textContent=t+'s';$('[data-q-wait]',root).textContent=pending.length;$('[data-q-done]',root).textContent=completed;}function enqueue(){if(pending.length>=8){log($('[data-q-log]',root),'BACKPRESSURE: waiting queue full. Reject new job.');return;}pending.push(++id);log($('[data-q-log]',root),`Enqueued job ${id}.`);draw();}draw();$('[data-enqueue]',root).onclick=enqueue;$('[data-enqueue-many]',root).onclick=()=>{for(let i=0;i<5;i++)enqueue();};$('[data-tick]',root).onclick=()=>{const workers=+$('[data-workers]',root).value;while(running.length<workers&&pending.length){const jid=pending.shift();running.push({id:jid,remaining:3});log($('[data-q-log]',root),`t=${t}s · worker starts job ${jid}.`);}t++;running.forEach(j=>j.remaining--);const done=running.filter(j=>j.remaining<=0);completed+=done.length;done.forEach(j=>log($('[data-q-log]',root),`t=${t}s · job ${j.id} completed.`));running=running.filter(j=>j.remaining>0);draw();};$('[data-workers]',root).onchange=()=>log($('[data-q-log]',root),'Worker target changed. Existing jobs finish; new slots apply next tick.');$('[data-q-reset]',root).onclick=()=>{pending=[];running=[];completed=0;t=0;id=0;draw();$('[data-q-log]',root).textContent='Queue reset.';};
}
if(type==='binary'){
const arr=[2,5,9,12,17,23,31,42,56,68,81,95];let lo=0,hi=arr.length-1,mid=-1,found=false,ended=false,tries=0,target=31;root.innerHTML=`<p class="lab-caption">Search a sorted array. Each comparison discards the half that cannot contain the target. Choose a missing value to see the not-found case.</p><div class="control-row"><label>Target<input data-target type="number" min="0" max="100" value="31"></label><button class="button orange" data-compare>Compare midpoint →</button><button class="button secondary" data-b-reset>Start / reset</button></div><div class="array-row" data-array></div><div class="result-callout" data-b-result></div><div class="console" data-b-log aria-live="polite">Ready. Search range is the entire array.</div>`;function draw(){$('[data-array]',root).innerHTML=arr.map((x,i)=>`<span class="array-cell ${i===mid?(found?'found':'mid'):''} ${i<lo||i>hi?'discard':''}">${x}</span>`).join('');$('[data-b-result]',root).textContent=`Target ${target} · ${tries} comparison${tries===1?'':'s'} · ${found?'found':ended?'not found':Math.max(0,hi-lo+1)+' candidates remain'}`;$('[data-compare]',root).disabled=ended;}function reset(){const v=Number($('[data-target]',root).value);if(!Number.isFinite(v)||$('[data-target]',root).value.trim()===''){toast('Enter a numeric target.');return;}target=v;lo=0;hi=arr.length-1;mid=-1;found=false;ended=false;tries=0;draw();$('[data-b-log]',root).textContent=`New search for ${target}.`;}draw();$('[data-b-reset]',root).onclick=reset;$('[data-target]',root).onchange=reset;$('[data-compare]',root).onclick=()=>{if(ended)return;mid=Math.floor((lo+hi)/2);tries++;if(arr[mid]===target){found=true;ended=true;log($('[data-b-log]',root),`Compare ${arr[mid]} with ${target}: found at index ${mid}.`);}else if(arr[mid]<target){log($('[data-b-log]',root),`${arr[mid]} < ${target}: discard indices through ${mid}.`);lo=mid+1;}else{log($('[data-b-log]',root),`${arr[mid]} > ${target}: discard index ${mid} and later.`);hi=mid-1;}if(lo>hi){ended=true;log($('[data-b-log]',root),'Empty interval: target is absent.');}draw();};
}
if(type==='isolation'){
let db=100,snapshot=null,phase=0;root.innerHTML=`<p class="lab-caption">Interleave two transactions. A reads, B commits 150, then A reads again. This model compares PostgreSQL Read Committed with its snapshot-based Repeatable Read.</p><div class="control-row"><label>A isolation<select data-iso><option value="rc">Read Committed</option><option value="rr">Repeatable Read</option></select></label><button class="button orange" data-iso-step>1. A reads balance</button><button class="button secondary" data-iso-reset>↻ Reset</button></div><div class="server-row"><div class="server"><small>COMMITTED DATABASE</small><b data-db>100</b></div><div class="server"><small>A LAST READ</small><b data-a>—</b></div><div class="server"><small>TRANSACTION A</small><b data-a-state style="font-size:16px">not started</b></div></div><div class="console" data-iso-log aria-live="polite">Initial committed balance: 100. Select isolation and step the schedule.</div>`;function reset(){db=100;snapshot=null;phase=0;$('[data-db]',root).textContent='100';$('[data-a]',root).textContent='—';$('[data-a-state]',root).textContent='not started';$('[data-iso-step]',root).disabled=false;$('[data-iso-step]',root).textContent='1. A reads balance';$('[data-iso]',root).disabled=false;$('[data-iso-log]',root).textContent='Reset: initial balance 100.';}$('[data-iso-step]',root).onclick=()=>{const select=$('[data-iso]',root);if(phase===0){snapshot=db;$('[data-a]',root).textContent=db;$('[data-a-state]',root).textContent='open';select.disabled=true;log($('[data-iso-log]',root),'A begins and reads 100. A snapshot baseline = 100.');$('[data-iso-step]',root).textContent='2. B commits 150';}else if(phase===1){db=150;$('[data-db]',root).textContent=db;log($('[data-iso-log]',root),'B updates balance to 150 and COMMITs. A remains open.');$('[data-iso-step]',root).textContent='3. A reads again';}else{const value=select.value==='rc'?db:snapshot;$('[data-a]',root).textContent=value;log($('[data-iso-log]',root),`A reads ${value}: ${select.value==='rc'?'new statement sees latest committed data (non-repeatable read).':'same transaction snapshot, despite B’s commit.'}`);$('[data-iso-step]',root).disabled=true;$('[data-a-state]',root).textContent='read complete';}phase++;};$('[data-iso-reset]',root).onclick=reset;
}
if(type==='circuit'){
let state='closed',failures=0,t=0,openedAt=null,dependency='down';root.innerHTML=`<p class="lab-caption">Three consecutive failures open the breaker for 5 model seconds. After cooldown, one request probes recovery. This model uses consecutive failures rather than a rolling production window.</p><div class="control-row"><label>Dependency<select data-dependency><option value="down">Failing</option><option value="up">Healthy</option></select></label><button class="button orange" data-call>Call dependency</button><button class="button secondary" data-c-time>+1 second</button><button class="button secondary" data-c-reset>↻ Reset</button></div><div class="server-row"><div class="server"><small>BREAKER STATE</small><b data-c-state style="font-size:22px">CLOSED</b></div><div class="server"><small>FAILURE COUNT</small><b data-c-fail>0</b></div><div class="server"><small>MODEL TIME</small><b data-c-clock>0s</b></div></div><div class="console" data-c-log aria-live="polite">Closed means calls are allowed. Failing dependency selected.</div>`;function draw(){$('[data-c-state]',root).textContent=state.toUpperCase();$('[data-c-fail]',root).textContent=failures;$('[data-c-clock]',root).textContent=t+'s';}function open(){state='open';openedAt=t;}function call(){dependency=$('[data-dependency]',root).value;if(state==='open'){log($('[data-c-log]',root),`t=${t}s · FAST FAIL: open circuit. ${Math.max(0,5-(t-openedAt))}s cooldown remains.`);return;}const probe=state==='half-open';if(dependency==='up'){state='closed';failures=0;log($('[data-c-log]',root),`t=${t}s · ${probe?'PROBE succeeded: close breaker.':'Call succeeded; reset consecutive failures.'}`);}else{failures++;log($('[data-c-log]',root),`t=${t}s · ${probe?'PROBE failed: reopen.':'Dependency failed.'}`);if(probe||failures>=3)open();}draw();}$('[data-call]',root).onclick=call;$('[data-c-time]',root).onclick=()=>{t++;if(state==='open'&&t-openedAt>=5){state='half-open';log($('[data-c-log]',root),`t=${t}s · cooldown elapsed. HALF-OPEN: next call is a probe.`);}draw();};$('[data-c-reset]',root).onclick=()=>{state='closed';failures=0;t=0;openedAt=null;draw();$('[data-c-log]',root).textContent='Breaker reset. Current dependency choice retained.';};
}
if(type==='shard'){
const keys=Array.from({length:18},(_,i)=>'user-'+(i+1));let n=3;const hash=s=>{let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;};root.innerHTML=`<p class="lab-caption">This is hash(key) modulo N, deliberately contrasted with consistent hashing. Change shard count to observe remapping. Hashing distributes keys, but not necessarily request popularity.</p><div class="control-row"><label>Shard count<select data-shards><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label></div><div class="partition-row" data-partitions></div><div class="console" data-shard-log aria-live="polite">Initial modulo routing with 3 shards.</div>`;function draw(){$('[data-partitions]',root).innerHTML=Array.from({length:n},(_,i)=>`<div class="server"><small>SHARD ${i}</small><b>${keys.filter(k=>hash(k)%n===i).length}</b><small>${keys.filter(k=>hash(k)%n===i).join(', ')||'empty'}</small></div>`).join('');}draw();$('[data-shards]',root).onchange=()=>{const before=n;n=+$('[data-shards]',root).value;const moved=keys.filter(k=>hash(k)%before!==hash(k)%n).length;draw();log($('[data-shard-log]',root),`${before} → ${n} shards: ${moved}/${keys.length} keys change numeric owner. Actual data migration is not implemented in this model.`);};
}
}
function render(scroll=true){stopActive();closeMenu();const raw=location.hash.slice(1)||'home';const [route,id]=raw.split('/');$('#search').value='';let mod=null,crumb='Overview';if(route==='lesson'){const l=lessons.find(x=>x.id===id);if(l){mod=l.module;crumb=moduleOf(mod).title;showLesson(l);document.title=l.title+' — Backend Atlas';}else showNotFound();}else if(route==='module'){const m=moduleOf(id);if(m){mod=m.id;crumb=m.title;showModule(m);}else showNotFound();}else if(route==='path'){crumb='Learning path';showPath();}else if(route==='saved'){crumb='Saved lessons';showSaved();}else if(route==='playground'){crumb='Playground';showPlayground(id);}else if(route==='home'){showHome();}else{showNotFound();}if(route!=='lesson')document.title=crumb+' — Backend Atlas';$('#crumb').textContent=crumb;activeNav(route,mod);if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function showNotFound(){main.innerHTML='<div class="empty"><h1>That page wandered off.</h1><p>Return to the learning path to find a lesson.</p><a class="button orange" href="#path">Open learning path →</a></div>';}
window.addEventListener('hashchange',()=>render());document.addEventListener('click',e=>{const link=e.target.closest('a');if(link?.getAttribute('href')==='#main'){e.preventDefault();main.focus();main.scrollIntoView();return;}if(link&&link.getAttribute('href')?.startsWith('#')&&!link.dataset.anchor&&link.getAttribute('href')!=='#main'){$('#search').value='';closeMenu();if(link.getAttribute('href')===location.hash){e.preventDefault();render();}}});matchMedia('(max-width:760px)').addEventListener('change',menuAccessibility);updateProgress();render();
})();
